def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def contains_only_small_digits(n):
    if n <= 0:
        return False
    return all(int(d) in {0, 1, 2} for d in str(n))

def solve():
    results = []
    # Targeted search up to n=1000
    for n in range(1, 1001):

        # 1. Check the targeted constraint: all numbers from n to n+37 must consist only of {0, 1, 2}
        all_small_digits = True
        for k in range(n, n + 38):
            if not contains_only_small_digits(k):
                all_small_digits = False
                break

        if not all_small_digits:
            continue

        # 2. If constraint is met, calculate the product of digit sums
        product_of_sums = 1
        all_sums_non_zero = True
        for k in range(n, n + 38):
            s_k = sum_digits(k)
            if s_k == 0: # Should not happen for positive integers, but good practice
                all_sums_non_zero = False
                break
            product_of_sums *= s_k

        if not all_sums_non_zero:
            continue

        # 3. Check divisibility by 11
        is_not_multiple_of_11 = (product_of_sums % 11 != 0)

        results.append({
            'n': n,
            'product_mod_11': product_of_sums % 11,
            'is_target_match': is_not_multiple_of_11,
            'is_digit_match': all_small_digits
        })


    print("--- Search Results Summary ---")
    count_digit_match = sum(1 for r in results if r['is_digit_match'])
    print(f"Number of n <= 1000 satisfying the strict digit constraint (n to n+37 only 0, 1, 2): {count_digit_match}")

    found_results = [r for r in results if r['is_target_match']]

    if found_results:
        print("\nFound 'n' where P(n) is NOT a multiple of 11:")
        for r in found_results:
            print(f"n = {r['n']}, Product mod 11 = {r['product_mod_11']}")
    else:
        print("\nNo 'n' found <= 1000 satisfying both constraints.")

    # Report on the distribution of S(n) values for the successful candidates (if any)
    if found_results:
        S_values = []
        for r in found_results:
            n = r['n']
            for k in range(n, n + 38):
                S_values.append(sum_digits(k))

        S_values.sort()
        print(f"\nDistribution of S(n) values across the sequence (if results found):")
